using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace MoreSpace {
static class DiskMetadata {
 public static List<Entry> Scan(string root,CancellationToken token){var result=new List<Entry>();if(!Engine.NoLinks(root))throw new IOException("Links não são percorridos.");var pending=new Stack<string>();pending.Push(root);while(pending.Count>0){token.ThrowIfCancellationRequested();var dir=pending.Pop();try{foreach(var info in new DirectoryInfo(dir).EnumerateFileSystemInfos()){token.ThrowIfCancellationRequested();if((info.Attributes&FileAttributes.ReparsePoint)!=0)continue;if(info is DirectoryInfo){if(info.Name=="$RECYCLE.BIN"||info.Name=="System Volume Information")continue;pending.Push(info.FullName);}else if(info.Name.Equals("Thumbs.db",StringComparison.OrdinalIgnoreCase)||info.Name==".DS_Store"){var file=(FileInfo)info;result.Add(new Entry{Path=file.FullName,Size=file.Length,Modified=file.LastWriteTimeUtc});}}}catch(IOException){}catch(UnauthorizedAccessException){}}return result;}
}
partial class MainWindow {
 ComboBox removable=new ComboBox();Label diskNote=new Label();
 void SetupExternalDisks(){var page=Page("Discos externos","Revise Thumbs.db e .DS_Store em unidades removíveis. Outros dados ficam fora da seleção. Discos USB classificados como fixos continuam disponíveis na Home.");var bar=new FlowLayoutPanel{Dock=DockStyle.Fill};removable.Width=260;removable.DropDownStyle=ComboBoxStyle.DropDownList;removable.Margin=new Padding(0,8,8,0);bar.Controls.Add(removable);bar.Controls.Add(Btn("Atualizar unidades",delegate{RefreshRemovable();}));bar.Controls.Add(Btn("Analisar metadados…",async delegate{await CleanDiskMetadata();}));bar.Controls.Add(Btn("Ejetar…",async delegate{if(busy||removable.SelectedItem==null)return;string root=(string)removable.SelectedItem;if(MessageBox.Show(this,"Solicitar ejeção de "+root+"? Feche arquivos desta unidade.","Ejetar",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;try{await Task.Run(()=>AppManager.Run("$s=New-Object -ComObject Shell.Application; $item=$s.Namespace(17).ParseName("+AppManager.Quote(root.TrimEnd('\\'))+"); if($null -eq $item){throw 'Unidade não encontrada'}; $item.InvokeVerb('Eject')"));diskNote.Text="Ejeção solicitada ao Windows. Confirme a notificação de remoção segura antes de desconectar.";}catch(Exception ex){MessageBox.Show(this,ex.Message);}}));page.Controls.Add(bar,0,1);diskNote.Dock=DockStyle.Fill;diskNote.Text="Clique em Atualizar unidades. A análise só lê os nomes e tamanhos.\r\nA Lixeira pode não estar disponível em pendrives; o Windows pode pedir confirmação adicional.\r\nArquivos AppleDouble (._*) não são removidos, pois podem guardar metadados importantes.";page.Controls.Add(diskNote,0,2);}
 void RefreshRemovable(){removable.Items.Clear();if(demoMode){removable.Items.Add("E:\\");}else foreach(var d in DriveInfo.GetDrives())try{if(d.IsReady&&d.DriveType==DriveType.Removable)removable.Items.Add(d.Name);}catch{}if(removable.Items.Count>0)removable.SelectedIndex=0;}
 async Task CleanDiskMetadata(){if(busy||demoMode||removable.SelectedItem==null)return;string root=(string)removable.SelectedItem;Busy(true);cts=new CancellationTokenSource();try{var entries=await Task.Run(()=>DiskMetadata.Scan(root,cts.Token));using(var dialog=new ChartFileDialog(null,entries)){if(dialog.ShowDialog(this)!=DialogResult.OK)return;int count=0;long bytes=0;var before=SavingsStore.Snapshot();foreach(var e in dialog.Selection)try{ChartFileRules.Validate(e,Path.GetDirectoryName(e.Path));if(!Engine.Under(e.Path,root))throw new IOException("Fora da unidade.");await Task.Run(()=>FileRemoval.Delete(e.Path,dialog.Permanent));count++;bytes+=e.Size;}catch(Exception ex){Log(e.Path+": "+ex.Message);}if(count>0)RecordSavings(dialog.Permanent?"Disco externo":"Via Lixeira (externo)",count,dialog.Permanent?(long?)bytes:null,before);diskNote.Text=count+" arquivos processados. Consulte Atividade para falhas.";}}catch(OperationCanceledException){diskNote.Text="Análise cancelada.";}catch(Exception ex){MessageBox.Show(this,ex.Message);}finally{cts.Dispose();cts=null;Busy(false);}}
}
}
